const t = $("When Called").first().json || {};
const cfgRows = $("Load Config").all().map(function (i) { return i.json; }).filter(function (r) { return r && r.config_key; });
const version = (t.canonical_product && t.canonical_product.taxonomy_version) || "v1";

// Build config map (no business logic hardcoded; all defaults come from tbk_pi_config)
const cfg = {};
cfgRows.forEach(function (r) {
  if (r.taxonomy_version && r.taxonomy_version !== version) return;
  let v = r.config_value;
  if (r.value_type === "json") { try { v = JSON.parse(r.config_value); } catch (e) { v = r.config_value; } }
  else if (r.value_type === "number") { v = Number(r.config_value); }
  else if (r.value_type === "boolean") { v = String(r.config_value).toLowerCase() === "true"; }
  cfg[r.config_key] = v;
});
function C(k, d) { return cfg[k] === undefined ? d : cfg[k]; }

// Canonical attributes from BUILD-305
const canonical = t.canonical_product || {};
const attrs = Array.isArray(canonical.attributes) ? canonical.attributes : [];
function pick(type) { return attrs.filter(function (a) { return a.attribute_type === type; }); }
const frosting = pick("frosting_type").map(function (a) { return a.normalized_value; });
const colors = pick("color").map(function (a) { return a.normalized_value; });
const decorations = pick("decoration").map(function (a) { return a.normalized_value; });

// Validation: required = at least one recognized attribute OR a canonical id
const validation_errors = [];
if (attrs.length === 0) validation_errors.push("no_canonical_attributes");
const image_id = t.image_id || canonical.image_id || "";
const batch_id = t.batch_id || canonical.batch_id || "";
if (!image_id) validation_errors.push("missing_image_id");

const primary_color = colors[0] || "";
const secondary_colors = colors.slice(1, 3);
const accent_colors = colors.slice(3);
const finish = frosting[0] || "";
const flowers = decorations.filter(function (d) { return /flower/i.test(d); });
const toppers = decorations.filter(function (d) { return /topper|figurine|candle/i.test(d); });
const characters = decorations.filter(function (d) { return /character|figurine/i.test(d); });
const writing_area = decorations.some(function (d) { return /text|letter|writing/i.test(d); });

// Confidence = average of attribute confidences
let confSum = 0, confN = 0;
attrs.forEach(function (a) { if (typeof a.confidence === "number") { confSum += a.confidence; confN++; } });
const confidence_score = confN ? Math.round((confSum / confN) * 100) / 100 : 0;

const vision = t.vision_result || {};
const brand = C("brand_name", "");
const product_type = C("product_type", "Cake");
const occasionList = C("occasions", []);

// Deterministic product name/title from real attributes + config
const descriptor = [finish, primary_color].filter(Boolean).join(" ");
const product_name = (descriptor ? descriptor + " " : "") + product_type;
const product_title = product_name + (brand ? " | " + brand : "");
const short_title = product_name;

// Slug from name + config base url
const site = C("site_base_url", "");
const slug = product_name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const source_models = [];
if (canonical.source_model) source_models.push(canonical.source_model);
if (vision.model_version) source_models.push(vision.model_version);

const product_id = "tbk_" + (image_id || ("gen_" + $runIndex + "_" + Date.now()));

// Assemble the deterministic base + SEO prompt for optional AI
const base = {
  product_id: product_id,
  image_id: image_id,
  batch_id: batch_id,
  canonical_id: (attrs[0] && attrs[0].canonical_id) || "",
  taxonomy_version: version,
  validation_errors: validation_errors,
  cfg: cfg,
  derived: {
    frosting: frosting, colors: colors, decorations: decorations,
    primary_color: primary_color, secondary_colors: secondary_colors, accent_colors: accent_colors,
    finish: finish, flowers: flowers, toppers: toppers, characters: characters, writing_area: writing_area,
    confidence_score: confidence_score, source_models: source_models,
    product_name: product_name, product_title: product_title, short_title: short_title, slug: slug
  }
};

// SEO generation prompt (uses allowed vocab from config, not hardcoded)
const seoModel = C("seo_model", "gpt-4o-mini");
const aiEnabled = C("ai_enabled", false);
const sys = "You are an e-commerce SEO copywriter for a premium bakery. Return ONLY compact JSON with keys: seo_title, meta_title, meta_description, focus_keywords (array), secondary_keywords (array), semantic_keywords (array), faq (array of {q,a}), alt_text, image_caption, og_title, og_description. Keep meta_description <=155 chars. No prose outside JSON.";
const userMsg = "Product: " + product_name + "\nBrand: " + brand + "\nType: " + product_type + "\nColors: " + JSON.stringify(colors) + "\nFrosting/Finish: " + finish + "\nDecorations: " + JSON.stringify(decorations) + "\nAllowed occasions: " + JSON.stringify(occasionList);
const seoBody = { model: seoModel, messages: [ { role: "system", content: sys }, { role: "user", content: userMsg } ], temperature: 0.4, response_format: { type: "json_object" } };
base.ai_enabled = aiEnabled;
base.seo_body_json = JSON.stringify(seoBody);
return [{ json: base }];

const base = $("Prepare & Normalize").first().json;
const d = base.derived;
const cfg = base.cfg;
function C(k, def) { return cfg[k] === undefined ? def : cfg[k]; }
const nowIso = new Date().toISOString();

// Parse SEO AI output if present (continue-on-error: may be absent)
let seoAI = {};
const resp = $json || {};
try {
  const content = resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : "";
  if (content) seoAI = JSON.parse(content);
} catch (e) { seoAI = {}; }
const aiOk = seoAI && Object.keys(seoAI).length > 0;

const brand = C("brand_name", "");
const site = C("site_base_url", "");
const canonicalUrl = site && d.slug ? (site + "/products/" + d.slug) : "";

// ---- PRODUCT ----
const product = {
  product_name: d.product_name, product_title: d.product_title, short_title: d.short_title,
  product_type: C("product_type", "Cake"), product_category: C("product_category", ""), subcategory: "",
  theme: "", occasion: "", recipient: "", age_group: "", gender: "", difficulty: "",
  style: d.finish, collection: "", luxury_level: (C("luxury_levels", [])[0] || ""),
  cake_type: C("product_type", "Cake"), shape: "", tiers: null,
  weight_options: C("weight_options", []), servings: null, customizable: true,
  eggless_available: C("eggless_available", null), flavour_options: C("flavour_options", []),
  primary_color: d.primary_color, secondary_colors: d.secondary_colors, accent_colors: d.accent_colors,
  texture: d.finish, finish: d.finish, decorations: d.decorations, flowers: d.flowers,
  characters: d.characters, toppers: d.toppers, writing_area: d.writing_area,
  packaging: "", delivery_type: C("delivery_type", []), preparation_time: C("preparation_time", ""),
  freshness: "Freshly baked", storage: C("storage", ""), allergens: C("allergens_default", []),
  ingredients_summary: "", USP: "", confidence_score: d.confidence_score,
  model_used: (d.source_models[0] || ""), vision_provider: (d.source_models[0] || "")
};

// ---- SEO (AI where available, deterministic fallback otherwise) ----
const seo = {
  seo_title: seoAI.seo_title || d.product_title,
  meta_title: seoAI.meta_title || d.product_title,
  meta_description: seoAI.meta_description || (d.product_name + " by " + brand),
  slug: d.slug, canonical_url: canonicalUrl,
  focus_keywords: seoAI.focus_keywords || [d.product_name],
  secondary_keywords: seoAI.secondary_keywords || [],
  semantic_keywords: seoAI.semantic_keywords || [],
  FAQ: seoAI.faq || [],
  schema_json: {
    "@context": "https://schema.org/", "@type": "Product", name: d.product_name,
    brand: { "@type": "Brand", name: brand }, category: C("product_category", ""), url: canonicalUrl
  },
  internal_link_targets: [], external_reference_keywords: [],
  alt_texts: [seoAI.alt_text || (d.product_name + " - " + brand)],
  image_filenames: [d.slug ? (d.slug + ".jpg") : ""],
  image_captions: [seoAI.image_caption || d.product_name],
  open_graph: { "og:title": seoAI.og_title || d.product_title, "og:description": seoAI.og_description || "", "og:type": "product", "og:url": canonicalUrl },
  twitter_card: { "twitter:card": "summary_large_image", "twitter:title": seoAI.seo_title || d.product_title, "twitter:description": seoAI.meta_description || "" },
  ai_generated: aiOk
};

// ---- SHOPIFY (prepared only; NOT published — BUILD-307 owns publishing) ----
const shopify = {
  title: d.product_title, body_html: "", vendor: C("vendor", ""), product_type: C("product_type", "Cake"),
  tags: (d.decorations.concat(d.colors, [d.finish]).filter(Boolean)), collections: [], handle: d.slug,
  status: C("default_status", "draft"), seo_title: seo.seo_title, seo_description: seo.meta_description,
  template_suffix: "", gift_card: C("gift_card", false), requires_shipping: C("requires_shipping", true),
  taxable: C("taxable", true), variant_defaults: { weight_options: C("weight_options", []) },
  metafields: [], search_keywords: seo.focus_keywords,
  google_product_category: C("google_product_category", ""),
  merchant_center_attributes: { brand: C("vendor", ""), condition: "new", availability: "in stock" }
};

// ---- AI SEARCH / KNOWLEDGE ----
const ai_search = {
  embedding_text: [d.product_name, C("product_category", ""), d.finish].concat(d.colors, d.decorations).filter(Boolean).join(" | "),
  knowledge_graph_entities: [d.product_name, C("product_category", ""), d.finish].filter(Boolean),
  entity_relationships: d.decorations.map(function (x) { return { subject: d.product_name, predicate: "hasDecoration", object: x }; }),
  semantic_summary: d.product_name + " with " + (d.finish || "frosting") + (d.colors.length ? (" in " + d.colors.join(", ")) : ""),
  vector_ready: false, cluster_id: "", similar_products: [], canonical_id: base.canonical_id
};

// ---- MARKETING (scaffold; owned by BUILD-312 Marketing Brain) ----
const marketing = {
  meta_ads_headlines: [], google_ads_headlines: [], google_ads_descriptions: [],
  instagram_caption: "", facebook_caption: "", whatsapp_caption: "", pinterest_caption: "",
  hashtags: [], CTA: "", campaign_tags: [], _owner: "BUILD-312 Marketing Brain"
};

// ---- ERP ----
const erp = {
  recipe_reference: "", production_notes: "", inventory_class: C("inventory_class", ""),
  packaging_requirements: "", pricing_group: C("pricing_group", ""), production_category: C("production_category", "")
};

// ---- WORKFLOW META ----
const wfmeta = {
  created_at: nowIso, updated_at: nowIso, workflow_version: "306.1.0",
  attribute_version: base.taxonomy_version, taxonomy_version: base.taxonomy_version,
  source_models: d.source_models, execution_time: nowIso, validation_errors: base.validation_errors
};

const product_intelligence = {
  product_id: base.product_id, batch_id: base.batch_id, image_id: base.image_id, canonical_id: base.canonical_id,
  product: product, seo: seo, shopify: shopify, ai_search: ai_search, marketing: marketing, erp: erp, workflow: wfmeta
};

return [{ json: {
  product_intelligence: product_intelligence,
  _store: {
    product_id: base.product_id, batch_id: base.batch_id, image_id: base.image_id, canonical_id: base.canonical_id,
    product_json: JSON.stringify(product), seo_json: JSON.stringify(seo), shopify_json: JSON.stringify(shopify),
    marketing_json: JSON.stringify(marketing), erp_json: JSON.stringify(erp), knowledge_json: JSON.stringify(ai_search),
    workflow_version: wfmeta.workflow_version, created_at: nowIso, updated_at: nowIso,
    status: base.validation_errors.length ? "completed_with_warnings" : "success"
  }
} }];
